INSERT INTO public.exam_sections (id, exam_id, title, order_index) VALUES ('exam-calculus-2-2022-sec-0', 'exam-calculus-2-2022', '一、单项选择题', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, title = EXCLUDED.title, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2022-s0-0', 'exam-calculus-2-2022', 'exam-calculus-2-2022-sec-0', 0, '设。则（）.', '设 $L_{1}:\\frac{x-3}{-2}=\\frac{y+4}{-5}=\\frac{z}{3},\\quad L_{2}:\\left\\{\\begin{aligned}&x=3t,\\\\ &y=-1+3t,\\\\ &z=2+7t,\\end{aligned}\\right.$ 。 $L_{3}:\\left\\{\\begin{aligned}&x+3y-4z=-1,\\\\ &2x+y-z=0,\\end{aligned}\\right.$ 则（）.', '["$L_{1} // L_{3}$","$L_{1} // L_{2}$","$L_{2} \\\\perp L_{3}$","$L_{1} \\\\perp L_{2}$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2022长沙理工大学高数A（二）期末', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2022-s0-1', 'exam-calculus-2-2022', 'exam-calculus-2-2022-sec-0', 0, '已知由方程确定，则（）.', '已知 $z = f(x, y)$ 由方程 $z^2 - \\frac{y}{x} = 0$ 确定，则（）.', '["$x\\\\frac{\\\\partial z}{\\\\partial x}-y\\\\frac{\\\\partial z}{\\\\partial y}=0$","$x\\\\frac{\\\\partial z}{\\\\partial x}+y\\\\frac{\\\\partial z}{\\\\partial y}=0$","$y\\\\frac{\\\\partial z}{\\\\partial x}-x\\\\frac{\\\\partial z}{\\\\partial y}=0$","$(\\\\frac{\\\\partial z}{\\\\partial x})^{2}+(\\\\frac{\\\\partial z}{\\\\partial y})^{2}=0$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2022长沙理工大学高数A（二）期末', 1) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2022-s0-2', 'exam-calculus-2-2022', 'exam-calculus-2-2022-sec-0', 0, '设，则在点处（）.', '设 $\\lim_{(x,y)\\to(0,0)}\\frac{f(x,y)-f(0,0)+2x-y}{\\sqrt{x^{2}+y^{2}}}=0$ ，则 $f(x,y)$ 在点 $(0,0)$ 处（）.', '["不连续","连续但两个偏导数不存在","可微","两个偏导数存在但不可微"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2022长沙理工大学高数A（二）期末', 2) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2022-s0-3', 'exam-calculus-2-2022', 'exam-calculus-2-2022-sec-0', 0, '设,，则（）.', '设 $D = \\{(x, y) | x^{2} + y^{2} \\leq 1, y \\geq 0\\}$ , $D_{1} = \\{(x, y) | x^{2} + y^{2} \\leq 1, x \\geq 0, y \\geq 0\\}$ ，则（）.', '["$\\\\iint_{D}|x|dxdy=2\\\\iint_{D_{1}}xdxdy$","$\\\\iint_{D}xy\\\\,dxdy=2\\\\iint_{D_{1}}xy\\\\,dxdy$","$\\\\iint_{D}x\\\\,dxdy=2\\\\iint_{D_{1}}x\\\\,dxdy$","$\\\\iint_{D}(x+y)dxdy=2\\\\iint_{D_{1}}(x+y)dxdy$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2022长沙理工大学高数A（二）期末', 3) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2022-s0-4', 'exam-calculus-2-2022', 'exam-calculus-2-2022-sec-0', 0, '若级数收敛，则级数（）收敛.', '若级数 $\\sum_{n=1}^{\\infty} a_n$ 收敛，则级数（）收敛.', '["$\\\\sum_{n=1}^{\\\\infty} |a_n|$","$\\\\sum_{n=1}^{\\\\infty} (-1)^n a_n$","$\\\\sum_{n=1}^{\\\\infty} a_n a_{n+1}$","$\\\\sum_{n=1}^{\\\\infty} \\\\frac{a_n + a_{n+1}}{2}$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2022长沙理工大学高数A（二）期末', 4) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
